import { applyUpdates } from './update';

interface Profile { name: string; age: number }
const p: Profile = { name: 'ada', age: 36 };

const updated: Profile = applyUpdates(p, { age: 37 });

// @ts-expect-error - wrong-typed field must not compile
applyUpdates(p, { age: 'old' });

// @ts-expect-error - unknown fields must not compile
applyUpdates(p, { nickname: 'a' });

test_setup_files.behavior_test.js:
const assert = require('assert');
const { applyUpdates } = require('./build/update.js');
const original = { name: 'ada', age: 36 };
const updated = applyUpdates(original, { age: 37 });
assert.deepStrictEqual(updated, { name: 'ada', age: 37 });
assert.deepStrictEqual(original, { name: 'ada', age: 36 }, 'original must NOT be mutated');
assert.notStrictEqual(updated, original, 'must return a new object');
const kept = applyUpdates(original, { name: undefined });
assert.strictEqual(kept.name, 'ada', 'explicit undefined must not clobber existing values');
console.log('PASS');

reference_solution.update.ts:
export function applyUpdates<T extends object>(obj: T, updates: Partial<T>): T {
  const out = { ...obj };
  for (const key of Object.keys(updates) as (keyof T)[]) {
    const value = updates[key];
    if (value !== undefined) {
      out[key] = value as T[keyof T];
    }
  }
  return out;
}

